// CSD_RATIONALE_BEGIN
// Primary failure modes in attempt 30:
//   1. Tiny span dominant (28/49 wrong): the grammar accepts single-variable names as
//      complete, so "<<n>>" or "<<end_time>>" closes after 1 token – wrong answers.
//   2. 5 unclosed spans: model opens "<<" near end of budget, runs out before ">>" is emitted.
//   3. Guidance "Keep the expression short" directly triggered tiny spans.
//
// Fixes applied:
//   A. Manual loop with a minConstrained=2 guard – CloseSpanIfComplete is not called
//      until at least 2 constrained tokens exist, preventing 1-token closures.
//   B. CloseSpanWithinBudget fallback after the main loop eliminates unclosed spans.
//   C. Guidance rewritten to emphasise the COMPLETE arithmetic formula, show
//      multi-operator examples, and remove any "keep it short" instruction.
//   D. Each loop iteration consumes exactly 1 token-step via either CloseSpanIfComplete
//      (+1 when closing, +0 otherwise) combined with ConstrainedStep (+1) in the
//      non-closing branch, or ConstrainedStep alone in the force branch.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Unconstrained branch: when RenderedEndsWith(generated,"<<") fires we set
//   currentConstrainedOut := [] which satisfies parser.IsValidPrefix([]) by the
//   precondition. All other updates (generated += [next]) leave inside/current
//   unchanged.
//   Constrained branch, |current| < 2: ConstrainedStep returns only EOS or a
//   parser-valid token; AppendConstrainedToken extends both generated and current
//   by one token with IsTokenValidNext checked, so parser.IsValidPrefix(current')
//   is preserved.
//   Constrained branch, |current| >= 2, closed: CloseSpanIfComplete's postcondition
//   sets insideConstrainedOut := false, making the implication vacuously true and
//   currentConstrainedOut := [], satisfying the non-constrained branch invariant.
//   Constrained branch, |current| >= 2, not closed: CloseSpanIfComplete leaves
//   state unchanged; subsequent ConstrainedStep + AppendConstrainedToken preserves
//   parser validity as above.
//   Post-loop CloseSpanWithinBudget: its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//   Unconstrained branch: appends at most 1 token to generated and steps grows
//   by 1, so the bound is preserved.
//   Constrained branch, |current| < 2: ConstrainedStep + AppendConstrainedToken
//   appends at most 1 token to generated; steps grows by 1. Bound preserved.
//   Constrained branch, |current| >= 2: CloseSpanIfComplete costs +1 when closing
//   (appends ">>" = at most 1 token) and +0 otherwise; ConstrainedStep on the
//   non-closing path costs +1 (appends at most 1 token to generated). In both
//   sub-branches steps grows by exactly 1, so |generated| grows by at most 1.
//   Post-loop CloseSpanWithinBudget: |generatedOut| <= |generated_at_exit| +
//   closeBudget = |generated_at_exit| + (maxSteps - steps_at_exit) <=
//   |generatedPrefix| + maxSteps. We then set steps := maxSteps. Bound holds.
// CSD_PROOF_SKETCH_END

generated            := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost                 := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. Work through ALL arithmetic calculations explicitly. " +
    "After ALL reasoning is complete, output ONE final answer in this EXACT format: <<int(EXPRESSION)>> " +
    "where EXPRESSION is the COMPLETE arithmetic formula using the problem variables. " +
    "Examples of correct final answers: " +
    "<<int(n1*w1 + n2*w2 + n3*w3)>>, " +
    "<<int(initial_amount - quantity*unit_price)>>, " +
    "<<int(((n1 - n2) * l * p) // t // 60)>>. " +
    "The expression must combine ALL relevant variables with the right operators. " +
    "Use only: variable names (no {braces}), integers, +, -, *, /, //, %, (, ), int(). " +
    "Do NOT use << >> for intermediate steps. No LaTeX, no {braces}, no ** operator. " +
    "The FINAL line of your answer must be the <<int(...)>> expression.");

  var steps: nat := 0;
  var minConstrained: nat := 2;

  while steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    if !insideConstrainedOut {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      if |currentConstrainedOut| >= minConstrained {
        // Enough tokens accumulated – check for completion first, then advance.
        var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
        steps := steps + 1;
        if closed {
          generated             := cg;
          insideConstrainedOut  := ci;
          currentConstrainedOut := cc;
        } else {
          var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
          if next == eosToken {
            break;
          } else {
            var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
            if valid {
              var g2, i2, c2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
              generated             := g2;
              insideConstrainedOut  := i2;
              currentConstrainedOut := c2;
            }
          }
        }
      } else {
        // Force at least minConstrained tokens before allowing span closure.
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
          if valid {
            var g2, i2, c2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
            generated             := g2;
            insideConstrainedOut  := i2;
            currentConstrainedOut := c2;
          }
        }
      }
    }
  }

  // Fallback: close any span left open at budget exhaustion.
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated             := cg;
    insideConstrainedOut  := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

